// The RAW encoded data in a GS1 DataMatrix starts with FNC1 (ASCII 232 in Code Page 437,
// or a special GS1-defined character depending on encoding). Elements:

// Fixed-length AIs concatenate directly (no separator needed).
//   01 (GTIN, 14 digits fixed): 01 08901234567895
//   17 (expiry, 6 digits fixed): 17 260101

// Variable-length AIs need a Group Separator (GS, ASCII 29) after them.
//   10 (batch, up to 20 chars): 10 BATCH99 <GS>
//   21 (serial, up to 20 chars): 21 SERIAL42

// Full payload for a pharma DataMatrix:
//   FNC1 01 08901234567895 17 260101 10 BATCH99 <GS> 21 SERIAL42

// Human-readable representation (for humans, not the code):
//   (01)08901234567895(17)260101(10)BATCH99(21)SERIAL42

/// Parse a raw GS1 DataMatrix scan value into a Map<AI, Value>.
/// Handles FNC1 (identifier) + Group Separator between variable-length AIs.
class Gs1Parser {
  static const _fnc1 = 0x1D;   // GS in element strings; some scanners strip the FNC1 identifier

  // AI catalog: length -1 = variable
  static const _fixedLen = <String, int>{
    '00': 18, '01': 14, '02': 14, '15': 6, '17': 6, '20': 2,
  };

  static Map<String, String> parse(String raw) {
    // Some scanners return '(01)…' human-readable; strip parentheses if present.
    if (raw.contains('(')) raw = raw.replaceAll('(', '').replaceAll(')', ']');

    // Strip leading FNC1 marker (`]d2` for DataMatrix or ASCII 0x1D from readers configured that way)
    // The exact leading marker depends on scanner config — normalize.
    if (raw.startsWith(String.fromCharCode(_fnc1))) raw = raw.substring(1);

    final result = <String, String>{};
    int i = 0;
    while (i < raw.length) {
      // AI is 2-4 chars; try 2 first, then extend if not recognized
      String ai = raw.substring(i, i + 2);
      i += 2;

      final fixed = _fixedLen[ai];
      if (fixed != null) {
        result[ai] = raw.substring(i, i + fixed);
        i += fixed;
      } else {
        // variable: read until GS (0x1D) or end
        final gs = raw.indexOf(String.fromCharCode(_fnc1), i);
        final end = gs < 0 ? raw.length : gs;
        result[ai] = raw.substring(i, end);
        i = end == raw.length ? end : end + 1;
      }
    }
    return result;
  }
}

// Example — pharma scan
final ais = Gs1Parser.parse('01089012345678951726010110BATCH99\u001D21SERIAL42');
print(ais['01']);   // 08901234567895
print(ais['17']);   // 260101
print(ais['10']);   // BATCH99
print(ais['21']);   // SERIAL42
